css:
.abas { width: min(640px, 100%); }

/* Escondidos mas focáveis: display:none tiraria o input da navegação por
   teclado e levaria junto a troca por setas, que é a razão de usar radio. */
.abas input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.abas-rotulos {
  display: inline-flex; gap: 4px;
  padding: 4px; margin-bottom: 20px;
  border: 1px solid var(--border); border-radius: 100px;
  background: var(--bg-alt);
}
.abas-rotulos label {
  padding: 9px 20px; border-radius: 100px; cursor: pointer;
  font-size: 13px; font-weight: 600; color: var(--text-muted);
  transition: color 0.2s ease, background-color 0.2s ease;
}
.abas-rotulos label:hover { color: var(--text); }

.painel { display: none; }
.painel h3 { margin: 0 0 10px; font-family: 'Sora', sans-serif; font-size: 17px; }
.painel p { margin: 0; color: var(--text-muted); line-height: 1.6; }

/* Uma regra por aba. É o custo do caminho sem JS, e o que limita o padrão a
   meia dúzia de abas. */
#aba-1:checked ~ .abas-rotulos label:nth-child(1),
#aba-2:checked ~ .abas-rotulos label:nth-child(2),
#aba-3:checked ~ .abas-rotulos label:nth-child(3) {
  background: var(--accent); color: var(--bg);
}

#aba-1:checked ~ .abas-paineis .painel:nth-child(1),
#aba-2:checked ~ .abas-paineis .painel:nth-child(2),
#aba-3:checked ~ .abas-paineis .painel:nth-child(3) {
  display: block;
}

/* Sem isto, quem usa teclado troca de aba sem ver onde está: o foco mora no
   input invisível. */
#aba-1:focus-visible ~ .abas-rotulos label:nth-child(1),
#aba-2:focus-visible ~ .abas-rotulos label:nth-child(2),
#aba-3:focus-visible ~ .abas-rotulos label:nth-child(3) {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
